#!/bin/sh

GITHUB_REPOSITORY=${GITHUB_REPOSITORY:-nodejs/node}
BOT_TOKEN=${BOT_TOKEN:-}

RELEASE_DATE=$1
RELEASE_LINE=$2
RELEASER=$3

if [ -z "$RELEASE_DATE" ] || [ -z "$RELEASE_LINE" ]; then
  echo "Usage: $0 <RELEASE_DATE> <RELEASE_LINE>"
  exit 1
fi

if [ -z "$GITHUB_REPOSITORY" ] || [ -z "$BOT_TOKEN" ]; then
  echo "Invalid value in env for GITHUB_REPOSITORY and BOT_TOKEN"
  exit 1
fi

HAS_MISSING_DEPS=
for dep in node gh git git-node awk; do
  command -v "$dep" > /dev/null || {
    echo "Required dependency $dep is missing" >&2
    HAS_MISSING_DEPS=1
  }
done
[ -z "$HAS_MISSING_DEPS" ] || exit 1

set -xe

git node release --prepare --skipBranchDiff --yes --releaseDate "$RELEASE_DATE"

HEAD_BRANCH="$(git rev-parse --abbrev-ref HEAD)"
HEAD_SHA="$(git rev-parse HEAD^)"

TITLE="$(git log -1 --format=%s)"

# GH rest API has an undocumented limit of 65536 char for the body, setting it
# to 65534 to account for the ellipsis and the final EOL.
TEMP_BODY="$(awk -v MAX_BODY_LENGTH="65534" \
    "/^## ${RELEASE_DATE}/,/^<a id=/{
      if (/^<a id=/) {exit;}
      if ((output_length += length(\$0) + 1) > MAX_BODY_LENGTH) {exit 1;}
      print
    }" "doc/changelogs/CHANGELOG_V${RELEASE_LINE}.md" || echo "…")"

# Create the proposal branch
gh api \
  --method POST \
  -H "Accept: application/vnd.github+json" \
  -H "X-GitHub-Api-Version: 2022-11-28" \
  "/repos/${GITHUB_REPOSITORY}/git/refs" \
   -f "ref=refs/heads/$HEAD_BRANCH" -f "sha=$HEAD_SHA"

# Create the proposal PR
PR_URL="$(gh api \
  --method POST \
  --jq .html_url \
  -H "Accept: application/vnd.github+json" \
  -H "X-GitHub-Api-Version: 2022-11-28" \
  "/repos/${GITHUB_REPOSITORY}/pulls" \
   -f "title=$TITLE" -f "body=$TEMP_BODY" -f "head=$HEAD_BRANCH" -f "base=v$RELEASE_LINE.x" -f draft=true)"

# Push the release commit to the proposal branch using `BOT_TOKEN` from the env
node --input-type=module - \
    "$GITHUB_REPOSITORY" \
    "$HEAD_BRANCH" \
    "$HEAD_SHA" \
    "$TITLE" \
    "$(git log -1 HEAD --format=%b | awk -v PR_URL="$PR_URL" '{sub(/^PR-URL: TODO$/, "PR-URL: " PR_URL)} 1' || true)" \
    "$(git show HEAD --diff-filter=d --name-only --format= || true)" \
    "$(git show HEAD --diff-filter=D --name-only --format= || true)" \
<<'EOF'
const [,,
  repo,
  branch,
  parentCommitSha,
  commit_title,
  commit_body,
  modifiedOrAddedFiles,
  deletedFiles,
] = process.argv;

import { readFileSync } from 'node:fs';
import util from 'node:util';

const query = `
mutation ($repo: String! $branch: String!, $parentCommitSha: GitObjectID!, $changes: FileChanges!, $commit_title: String!, $commit_body: String) {
  createCommitOnBranch(input: {
    branch: {
      repositoryNameWithOwner: $repo,
      branchName: $branch
    },
    message: {
      headline: $commit_title,
      body: $commit_body
    },
    expectedHeadOid: $parentCommitSha,
    fileChanges: $changes
  }) {
    commit {
      url
    }
  }
}
`;
const response = await fetch('https://api.github.com/graphql', {
  method: 'POST',
  headers: {
    'Authorization': `bearer ${process.env.BOT_TOKEN}`,
  },
  body: JSON.stringify({
    query,
    variables: {
      repo,
      branch,
      parentCommitSha,
      commit_title,
      commit_body,
      changes: {
        additions: modifiedOrAddedFiles.split('\n').filter(Boolean)
          .map(path => ({ path, contents: readFileSync(path).toString('base64') })),
        deletions: deletedFiles.split('\n').filter(Boolean),
      }
    },
  })
});
if (!response.ok) {
  console.log({statusCode: response.status, statusText: response.statusText});
  process.exitCode ||= 1;
}
const data = await response.json();
if (data.errors?.length) {
  throw new Error('Endpoint returned an error', { cause: data });
}
console.log(util.inspect(data, { depth: Infinity }));
EOF

gh pr edit "$PR_URL" --add-label release --add-label "v$RELEASE_LINE.x" --add-assignee "$RELEASER"

#!/bin/sh

set -xe

# shellcheck disable=SC2016
gh api graphql -F "prID=$(gh pr view "$1" --json id --jq .id || true)" -f query='
mutation RebasePR($prID: ID!) {
    updatePullRequestBranch(input:{pullRequestId:$prID,updateMethod:REBASE}) {
        clientMutationId
    }
}'

sudo apt-get update
sudo apt-get install -y zsh ${{ matrix.awk }}
if [ "${{ matrix.shell }}" != "sh" ] && [ "${{ matrix.shell }}" != "bash" ] && [ "${{ matrix.shell }}" != "zsh" ]; then
  sudo apt-get install -y ${{ matrix.shell }}
fi
# Set the selected awk as the default
sudo update-alternatives --set awk /usr/bin/${{ matrix.awk }}

# Get Project data
gh api graphql -f query='
  query($org: String!, $number: Int!) {
    organization(login: $org){
      projectV2(number: $number) {
        id
        fields(first:20) {
          nodes {
            ... on ProjectV2Field {
              id
              name
            }
          }
        }
      }
    }
  }' -f org=$ORGANIZATION -F number=$PROJECT_NUMBER > project_data.json

# Parse project data
cat >> "$GITHUB_ENV" <<EOF
PROJECT_ID=$(jq '.data.organization.projectV2.id' project_data.json)
PLUGIN_FIELD_ID=$(jq '.data.organization.projectV2.fields.nodes[] | select(.name == "Plugin") | .id' project_data.json)
THEME_FIELD_ID=$(jq '.data.organization.projectV2.fields.nodes[] | select(.name == "Theme") | .id' project_data.json)
EOF

item_id="$(gh api graphql -f query='
  mutation($project: ID!, $content: ID!) {
    addProjectV2ItemById(input: {projectId: $project, contentId: $content}) {
      item {
        id
      }
    }
  }
' -f project="$PROJECT_ID" -f content="$ISSUE_OR_PR_ID" --jq '.data.addProjectV2ItemById.item.id')"

echo "ITEM_ID=$item_id" >> $GITHUB_ENV

# Get the list of modified files in the PR, and extract plugins and themes
gh pr view "$PR_NUMBER" \
  --repo "$GITHUB_REPOSITORY" \
  --json files --jq '.files.[].path' | awk -F/ '
  BEGIN {
    plugins = 0
    themes = 0
  }
  /^plugins\// {
    if (plugin == $2) next
    plugin = $2
    plugins++
  }
  /^themes\// {
    gsub(/\.zsh-theme$/, "", $2)
    if (theme == $2) next
    theme = $2
    themes++
  }
  END {
    # plugin and theme are values controlled by the PR author
    # so we should sanitize them before using anywhere else
    if (plugins == 1) {
      gsub(/[^a-zA-Z0-9._-]/, "", plugin)
      print "PLUGIN=" plugin
    }
    if (themes == 1) {
      gsub(/[^a-zA-Z0-9._-]/, "", theme)
      print "THEME=" theme
    }
  }
' >> "$GITHUB_ENV"

gh api graphql -f query='
  mutation (
    $project: ID!
    $item: ID!
    $plugin_field: ID!
    $plugin_value: String!
    $theme_field: ID!
    $theme_value: String!
  ) {
    set_plugin: updateProjectV2ItemFieldValue(input: {
      projectId: $project
      itemId: $item
      fieldId: $plugin_field
      value: {
        text: $plugin_value
      }
    }) {
      projectV2Item {
        id
      }
    }
    set_theme: updateProjectV2ItemFieldValue(input: {
      projectId: $project
      itemId: $item
      fieldId: $theme_field
      value: {
        text: $theme_value
      }
    }) {
      projectV2Item {
        id
      }
    }
  }
' -f project="$PROJECT_ID" -f item="$ITEM_ID" \
  -f plugin_field="$PLUGIN_FIELD_ID" -f plugin_value="$PLUGIN" \
  -f theme_field="$THEME_FIELD_ID" -f theme_value="$THEME" \
  --silent

${INSTALL} -d ${SHARE_DIR}
${INSTALL} -d ${SHARE_DIR}/.config
${INSTALL} -d ${SHARE_DIR}/.config/znt
${INSTALL} -d ${DOC_DIR}
cp zsh-navigation-tools.plugin.zsh _n-kill doc/znt-tmux.zsh ${SHARE_DIR}
cp README.md NEWS LICENSE doc/img/n-history2.png ${DOC_DIR}
if [ x"true" = x"`git rev-parse --is-inside-work-tree 2>/dev/null`" ]; then  git rev-parse HEAD;  else  cat .revision-hash;  fi > ${SHARE_DIR}/.revision-hash
:
for fname in n-*; do cp "$$fname" ${SHARE_DIR}; done;  for fname in znt-*; do cp "$$fname" ${SHARE_DIR}; done;  for fname in .config/znt/n-*; do cp "$$fname" ${SHARE_DIR}/.config/znt; done;

bun -e '
